-- Cardoso Marketing Hub — Produtos (catálogo 2026) + Auditoria de Mídias (Fase 2)
-- Roda uma vez no SQL Editor do Supabase, depois de rodar 0001_init.sql.

create extension if not exists pgcrypto;

create table public.products (
  id uuid primary key default gen_random_uuid(),
  code text not null,
  name text not null,
  brand_id uuid not null references public.brands (id),
  line text not null default '',
  age_range text not null default '',
  dimensions text not null default '',
  licensed boolean not null default false,
  needs_review boolean not null default false,
  catalog_page integer,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index on public.products (brand_id);
create unique index products_code_key on public.products (code);

alter table public.products enable row level security;
create policy "products_select_authenticated" on public.products for select to authenticated using (true);
create policy "products_write_authenticated" on public.products for insert to authenticated with check (true);
create policy "products_update_authenticated" on public.products for update to authenticated using (true);
create policy "products_delete_privileged" on public.products for delete to authenticated using (public.is_privileged());

-- Auditoria de mídias: uma linha por produto COM pendência conhecida, dentro de um projeto.
-- Produtos sem linha aqui são tratados como "Sem pendência" pelo Hub (ver Correções no projeto).
create table public.audit_items (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.projects (id) on delete cascade,
  product_id uuid not null references public.products (id) on delete cascade,
  item_to_change text not null default '',
  change_needed text not null default '',
  responsible text not null default '',
  correction_status text not null default 'Não Iniciado'
    check (correction_status in ('Sem pendência', 'Não Iniciado', 'Em Andamento', 'Corrigido')),
  packaging_status text not null default 'Não Iniciado',
  available boolean not null default false,
  priority_effective text not null default 'Média',
  verified_by text not null default '',
  verified_at date,
  drive_link text not null default '',
  notes text not null default '',
  risk_flag text not null default '',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (project_id, product_id)
);
create index on public.audit_items (project_id);
create index on public.audit_items (product_id);

alter table public.audit_items enable row level security;
create policy "audit_items_select_authenticated" on public.audit_items for select to authenticated using (true);
create policy "audit_items_write_authenticated" on public.audit_items for insert to authenticated with check (true);
create policy "audit_items_update_authenticated" on public.audit_items for update to authenticated using (true);
create policy "audit_items_delete_privileged" on public.audit_items for delete to authenticated using (public.is_privileged());

